// ======================================================
// 1. OBTENER INPUT (desde sub-workflow o input directo)
// ======================================================
let input = {};
try {
    input = $('When Executed by Another Workflow').first().json;
} catch (e) {
    input = $input.first().json;
}

// ======================================================
// 2. DATOS EMPRESA
// ======================================================
const datosEmpresa = {
    razon_social_profesional: input.nombre_profesional,
    direccion_profesional: input.Direccion_profesional,
    iibb_profesional: input.iibb_profesional,
    inicio_actividades: input.inicio_actividades,
    condicion_iva_profesional: input.categoria_iva,
    cuit_profesional: input.cuit_profesional,
    punto_de_venta: Number(input.punto_venta || 2),
    logo_url: ""
};

// ======================================================
// 3. DATOS CLIENTE
// ======================================================
const datosCliente = {
    cliente: input.nombre_cliente || "Consumidor Final",
    cuit_o_dni: input.cuit_Cliente || "0",
    condicion_iva_cliente: input.categoria_iva_cliente || "Consumidor Final",
    direccion_cliente: input.direccion_cliente || "Domicilio no informado",
    condicion_venta: input.condicion_venta || "Contado"
};

// ======================================================
// 4. TIPO DE COMPROBANTE
// ======================================================
let cbteTipo = 6; // Factura B por defecto
if (String(datosCliente.condicion_iva_cliente).toLowerCase().includes('inscripto')) {
    cbteTipo = 1; // Factura A
}

const esFacturaA = cbteTipo === 1;

// ======================================================
// 5. DOCUMENTO RECEPTOR
// ======================================================
let docTipo = 99;
let docNro = 0;

const rawDoc = String(datosCliente.cuit_o_dni).replace(/\D/g, '');

if (rawDoc.length === 11) {
    docTipo = 80; // CUIT
    docNro = Number(rawDoc);
} else if (rawDoc.length >= 7) {
    docTipo = 96; // DNI
    docNro = Number(rawDoc);
}

// Validación obligatoria Factura A
if (esFacturaA && docTipo !== 80) {
    throw new Error('Factura A requiere CUIT del cliente');
}

// ======================================================
// 6. CÁLCULOS DE IMPORTES
// ======================================================
const TASA_IVA = 0.21;

let impNeto = 0;
let impIVA = 0;
let impTotal = 0;

const montoInput = parseFloat(input.monto || 0);

if (esFacturaA) {
    // Factura A → el monto es NETO
    impNeto = montoInput;
    impIVA = parseFloat((impNeto * TASA_IVA).toFixed(2));
    impTotal = parseFloat((impNeto + impIVA).toFixed(2));
} else {
    // Factura B → el monto es TOTAL
    impTotal = montoInput;
    impNeto = parseFloat((impTotal / (1 + TASA_IVA)).toFixed(2));
    impIVA = parseFloat((impTotal - impNeto).toFixed(2));
}

// ======================================================
// 7. IVA (solo cuando corresponde)
// ======================================================
let ivaArray = [];

if (impIVA > 0) {
    ivaArray = [{
        Id: 5,           // 21%
        BaseImp: impNeto,
        Importe: impIVA
    }];
}

// ======================================================
// 8. CONDICIÓN IVA RECEPTOR
// ======================================================
let condicionIVAReceptorId = 5; // Consumidor Final

if (esFacturaA) {
    condicionIVAReceptorId = 1; // Responsable Inscripto
}

// ======================================================
// 9. FECHA AFIP
// ======================================================
const fechaAFIP = new Date().toISOString().slice(0, 10).replace(/-/g, "");

// ======================================================
// 10. SALIDA FINAL
// ======================================================
return [{
    json: {
        // PDF
        ...datosEmpresa,
        ...datosCliente,
        concepto_descripcion: input.concepto || "Servicios",
        impNeto,
        impIVA,
        impTotal,
        fecha: fechaAFIP,

        // Certificado
        ticket_payload: {
            isProdEnvironment: true,
            service: 'wsfe',
            cuit: datosEmpresa.cuit_profesional,
            fileName: input.archivo || 'goodapps.p12',
            folderFile: input.carpeta || 'GoodApps',
            password: '1234'
        },

        // AFIP
        wsfe_payload: {
            auth: {
                token: $('Obtener tiket').first().json.token,
                sign: $('Obtener tiket').first().json.sign,
                cuitRepresentada: datosEmpresa.cuit_profesional
            },
            feCAERequest: {
                feCabReq: {
                    CantReg: 1,
                    PtoVta: datosEmpresa.punto_de_venta,
                    CbteTipo: cbteTipo
                },
                feDetReq: [{
                    Concepto: 2,
                    DocTipo: docTipo,
                    DocNro: docNro,
                    CbteDesde: 0,
                    CbteHasta: 0,
                    CbteFch: fechaAFIP,

                    ImpTotal: impTotal,
                    ImpTotConc: 0,
                    ImpNeto: impNeto,
                    ImpOpEx: 0,
                    ImpTrib: 0,
                    ImpIVA: impIVA,

                    FchServDesde: fechaAFIP,
                    FchServHasta: fechaAFIP,
                    FchVtoPago: fechaAFIP,

                    MonId: 'PES',
                    MonCotiz: 1,

                    condicionIVAReceptorId,
                    Iva: ivaArray
                }]
            }
        }
    }
}];

