// ======================================================
// 1. OBTENER INPUT
// ======================================================
let input = {};
try {
  input = $('When Executed by Another Workflow').first().json;
} catch (e) {
  input = $input.first().json;
}

// ======================================================
// 2. TOKEN LIMPIO
// ======================================================
const tokenData = $('Obtener tiket').first().json;

const tokenLimpio = String(tokenData.token || '')
  .trim()
  .replace(/\s+/g, '');

const signLimpio = String(tokenData.sign || '')
  .trim()
  .replace(/\s+/g, '');

// ======================================================
// 3. TIPO DE COMPROBANTE
// ======================================================
const emisorRI = String(input.categoria_iva || '')
  .toLowerCase()
  .includes('inscripto');

const clienteRI = String(input.categoria_iva_cliente || '')
  .toLowerCase()
  .includes('inscripto');

let cbteTipo = 11; // Factura C por defecto

if (emisorRI && clienteRI) {
  cbteTipo = 1; // Factura A
} else if (emisorRI && !clienteRI) {
  cbteTipo = 6; // Factura B
}

// ======================================================
// 4. LIMPIAR CUIT EMISOR
// ======================================================
const cuitProfesionalLimpio = Number(
  String(input.cuit_profesional || '').replace(/\D/g, '')
);

// ======================================================
// 5. LIMPIAR CUIT CLIENTE (DEL AGENTE O DEL INPUT)
// ======================================================
// El agente puede devolverlo como:
// - cuit_cliente
// - cuitCliente
// - cuit
// - dentro de un texto
let cuitClienteRaw =
  input.cuit_cliente ??
  input.cuitCliente ??
  input.cuit ??
  '';

// Si viene embebido en texto, sacamos solo números
const cuitClienteLimpio = Number(
  String(cuitClienteRaw).replace(/\D/g, '')
);

// ======================================================
// 6. VALIDACIÓN CLARA (evita AFIP 500)
// ======================================================
if (cbteTipo === 1) {
  if (!cuitClienteLimpio || String(cuitClienteLimpio).length !== 11) {
    throw new Error('Factura A requiere CUIT válido del cliente');
  }
}

// ======================================================
// 7. RETURN
// ======================================================
return [{
  json: {
    ...input,

    // AFIP
    cbteTipo,
    punto_venta: Number(input.punto_venta || 2),

    // CUITs LIMPIOS
    cuit_profesional_limpio: cuitProfesionalLimpio,
    cuit_cliente_limpio: cuitClienteLimpio,

    // Tokens
    token: tokenLimpio,
    sign: signLimpio
  }
}];
